    {
      "id": 1,
      "claim": "A rational consumer chooses the quantity of a good that maximizes net benefit (total benefit minus total cost).",
      "evidence": "Standard micro‑economic theory of consumer choice; utility maximization principle.",
      "weight": 0.3,
      "depends_on": []
    },
    {
      "id": 2,
      "claim": "At the optimum, the marginal benefit of the next unit equals its marginal cost (MB = MC).",
      "evidence": "First‑order condition for maximization of net benefit: if MB > MC the consumer would gain by consuming more; if MB < MC the consumer would gain by consuming less.",
      "weight": 0.9,
      "depends_on": [1]
    },
    {
      "id": 3,
      "claim": "Therefore the consumer stops eating when MB = MC for the next cookie.",
      "evidence": "Direct implication of step 2; consumption ceases when the condition no longer holds for an additional unit.",
      "weight": 0.8,
      "depends_on": [2]
    },
    {
      "id": 4,
      "claim": "Option (B) states exactly this condition: \"the marginal benefit equals the marginal cost of the next cookie.\"",
      "evidence": "Text of option (B).",
      "weight": 0.7,
      "depends_on": [3]
    }
  ],
  "answer": "B",
  "confidence": 0.98,
  "considered": [
    {
      "answer": "A",
      "reason_rejected": "Total benefit equals total cost is a break‑even condition, not the utility‑maximizing condition for a rational consumer."
    },
    {
      "answer": "C",
      "reason_rejected": "Maximizing marginal cost would imply consuming until the cost is highest, which contradicts rational behavior."
    },
    {
      "answer": "D",
      "reason_rejected": "Minimizing marginal benefit would lead to zero consumption, not the optimal stopping rule."
    }
  ]
}
